const TSE_ES = G('es', 'tse', 'TSE')

const PODER_EN = 'PoderData/Aya of Jul 30 (n=2,400, field Jul 26 to 29, 2pp margin, 95% confidence, BR-07845/2026, telephone on mobile and landline, 677 municipalities across the 27 states)'
const PODER_ES = 'PoderData/Aya del 30 de julio (n=2.400, campo del 26 al 29 de julio, margen de 2pp, 95% de confianza, BR-07845/2026, telefónica en celular y fijo, 677 municipios en los 27 estados)'
const PODER2_EN = 'PoderData/Aya of Jul 30 (n=2,400, field Jul 26 to 29, 2pp margin, BR-07845/2026, telephone, 677 municipalities across the 27 states)'
